<header class="page-header"><div><h1><?= e(t('Review with LifeOS AI')) ?></h1><p class="muted"><?= e(t('Check the summary and edit each proposed task before saving.')) ?></p></div><a href="/intelligence"><?= e(t('Back')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<section class="card" id="understand-result" <?php if(in_array($job['status'],['queued','running'],true)): ?>hx-get="/intelligence/understand/<?= e($job['id']) ?>" hx-trigger="every 2s" hx-select="#understand-result" hx-target="this" hx-swap="outerHTML"<?php endif; ?>>
<?php if(in_array($job['status'],['queued','running'],true)): ?><p role="status"><?= e(t('Preparing your summary and task suggestions…')) ?></p>
<?php elseif($job['status']==='failed'): ?><p role="alert"><?= e(t('LifeOS AI is temporarily unavailable. Please try again shortly.')) ?></p><form method="post" action="/intelligence/understand"><?= csrf_field() ?><input type="hidden" name="text" value="<?= e($job['question']) ?>"><?php if(isset($job['workflow']['source'])): ?><input type="hidden" name="source" value="<?= e($job['workflow']['source']) ?>"><input type="hidden" name="share_source" value="yes"><?php endif; ?><?php if($job['workflow']['tasks']): ?><input type="hidden" name="share_tasks" value="yes"><?php endif; ?><p class="footnote"><?= e(t('Retry sends the same selected text and current task list online again.')) ?></p><button><?= e(t('Try again')) ?></button></form>
<?php else: ?><h2><?= e(t('Summary')) ?></h2><p class="assistant-summary"><?= nl2br(e(OpenCodeCliProvider::answer($job))) ?></p>
<?php $proposals=OpenCodeCliProvider::proposals($job); foreach($proposals as $index=>$proposal): if(!in_array($proposal['action'],['add_task','move_task'],true))continue; ?><article class="lesson-entry"><h3><?= e(t($proposal['action']==='move_task'?'Move task':'New task')) ?></h3><?php if(Db::one('SELECT 1 FROM ai_applied_actions WHERE job_id=? AND action_index=?',[$job['id'],$index])): ?><p role="status"><?= e(t('Saved')) ?></p><?php else: ?><form class="form-grid" method="post" action="/intelligence/understand/<?= e($job['id']) ?>/apply"><?= csrf_field() ?><input type="hidden" name="index" value="<?= e($index) ?>"><label><?= e(t('Task title')) ?><input name="title" maxlength="200" value="<?= e($proposal['title']) ?>" required <?= $proposal['action']==='move_task'?'readonly':'' ?>></label><label><?= e(t('Due date')) ?><input type="date" name="due" value="<?= e($proposal['due'] ?? '') ?>" <?= $proposal['action']==='move_task'?'required':'' ?>></label><div class="full"><button><?= e(t('Confirm and apply')) ?></button></div></form><?php endif; ?></article><?php endforeach; ?><?php if(!$proposals): ?><p class="muted"><?= e(t('No task changes were proposed. You can keep the summary and enter a task yourself.')) ?></p><?php endif; ?><p class="footnote"><?= e(t('Task moves can be undone in Recent actions.')) ?></p><?php endif; ?>
</section>
